<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue'
import FpDialog from '@/components/FpDialog.vue'
import {useAuthStore} from '@/stores/auth'
import {useLegacyChatRedPacketsStore} from '@/stores/legacyChatRedPackets'
import {legacyPacketRisk} from '@/api/legacy/chat-red-packets'
import {fpConfirm} from '@/composables/useDialog'
const auth=useAuthStore(),store=useLegacyChatRedPacketsStore(),gesture=ref<number|string>(''),confirming=ref(false),error=ref('')
let abort:AbortController|null=null
function cancel(){abort?.abort();abort=null;confirming.value=false}
const identity=()=>JSON.stringify([auth.apiKey,auth.account?.oId||''])
async function claim(){const d=store.detail;if(!d?.canClaim||store.busy||store.pending||confirming.value)return;error.value='';if(d.type==='rockPaperScissors'&&!(typeof gesture.value==='number'&&[0,1,2].includes(gesture.value))){error.value='请先明确选择出拳';return}cancel();const controller=new AbortController(),reader=identity(),choice=gesture.value;abort=controller;confirming.value=true
 const risk=d.type==='heartbeat'?`心跳可能领取负积分并扣款，领取前余额至少为红包显示金额${d.money}积分。`:d.type==='rockPaperScissors'?`猜拳可能增加或扣除${d.money}积分，平局本人不增减，发送者退款按服务器结算。领取前余额至少为${d.money}积分。`:'将领取一份红包，实际金额以当前领取记录为准，可能为0。'
 const yes=await fpConfirm({title:legacyPacketRisk(d.type)?'确认领取风险':'确认领取红包',message:risk+' 旧接口没有幂等恢复，不会自动重发领取操作，是否继续？',confirmText:legacyPacketRisk(d.type)?'接受风险并领取':'确认领取',signal:controller.signal})
 if(yes&&!controller.signal.aborted&&reader===identity()&&store.detail===d)await store.claim(d.id,d.type,{...(legacyPacketRisk(d.type)?{riskAccepted:true as const}:{}),...(d.type==='rockPaperScissors'?{gesture:choice as number}:{})});if(abort===controller){abort=null;confirming.value=false}}
watch(()=>store.detail,()=>{cancel();gesture.value='';error.value=''});watch(identity,cancel,{flush:'sync'});onBeforeUnmount(cancel)
const label=(type:string)=>({random:'拼手气',average:'普通',specify:'专属',heartbeat:'心跳',rockPaperScissors:'猜拳'}[type]||type)
</script>
<template><FpDialog :open="!!store.selectedId" title="红包详情" :width="560" @close="store.close"><p v-if="store.loading" role="status">正在读取红包…</p><p v-if="store.detailError" role="alert">{{ store.detailError }} <button type="button" @click="store.open()">重试红包详情</button></p><div v-if="store.detail" class="packet-detail"><p>{{ store.detail.message||'红包' }} · {{ label(store.detail.type) }}</p><p>发送者：{{ store.detail.sender.userName }}</p><p>已领取 {{ store.detail.got }}/{{ store.detail.count }}；红包显示金额 {{ store.detail.money }} 积分。原扣款与税额请查看积分记录。</p><p v-if="store.detail.recipientNames">接收人：{{ store.detail.recipientNames.join('、') }}</p><p v-if="store.detail.senderGesture!==undefined">发送者出拳：{{ ['石头','剪刀','布'][store.detail.senderGesture] }}</p><p v-if="store.detail.currentUserClaim">本人已领取，本次积分变化 {{ store.detail.currentUserClaim.amount }}{{ store.detail.currentUserClaim.amount<0?'（扣款）':'' }}。</p><p v-if="store.detail.got===store.detail.count">红包已领完。</p><label v-if="store.detail.canClaim&&store.detail.type==='rockPaperScissors'">你的出拳<select v-model.number="gesture" :disabled="store.busy||!!store.pending||confirming"><option value="" disabled>请选择</option><option :value="0">石头</option><option :value="1">剪刀</option><option :value="2">布</option></select></label><button v-if="store.detail.canClaim" type="button" :disabled="store.busy||!!store.pending||confirming" @click="claim">{{ legacyPacketRisk(store.detail.type)?'确认风险后领取':'领取一份' }}</button><p v-if="error" role="alert">{{ error }}</p><button type="button" :disabled="store.loading" @click="store.open()">刷新详情</button><ul><li v-for="row in store.detail.claims" :key="row.userId">{{ row.userName }}：{{ row.amount }}积分{{ row.amount<0?'（扣款）':'' }} · {{ new Date(row.time).toLocaleString() }}</li></ul></div><p>查看详情只读取消息，不会领取。旧接口缺少的税额与原支付金额不作推算。</p></FpDialog></template>
<style scoped lang="scss">.packet-detail{overflow-wrap:anywhere}p,li,label{font-size:13px}ul{padding-left:20px}button,select{font:inherit;margin:4px;padding:5px 8px;border:1px solid var(--fp-border);border-radius:5px;background:var(--fp-card);color:var(--fp-text)}[role=alert]{color:#bd503c}</style>
